import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'Test.'});
const session = (): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
});

function createMockProvider(usage: UsageMetadata): AIProvider {
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: 'response'};
      yield {type: 'stop', stopReason: 'end_turn', usage};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

describe('afterModelResponse usage contract', () => {
  it('receives usage metadata through the hook', async () => {
    const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    let received: UsageMetadata | undefined;

    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, u) => {
        received = u;
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider(usage), promptBuilder, undefined, {hooks});
    await orchestrator.processMessage(session());

    expect(received).toEqual(usage);
  });
});

