function createMultiRoundProvider(usages: UsageMetadata[]): AIProvider {
  let round = 0;
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: `round ${round}`};
      if (round < usages.length - 1) {
        yield {type: 'tool_use', toolCall: {id: `call-${round}`, name: 'test', input: {}}};
        yield {type: 'stop', stopReason: 'tool_use', usage: usages[round++]};
      } else {
        yield {type: 'stop', stopReason: 'end_turn', usage: usages[round++]};
      }
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const testRegistry = (): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'test', description: 'Test tool.', inputSchema: {type: 'object'}},
    async () => 'ok'
  );
  return registry;
};

describe('afterModelResponse usage accumulation', () => {
  it('accumulates usage across multiple tool rounds', async () => {
    const usages: UsageMetadata[] = [
      {inputTokens: 10, outputTokens: 2, totalTokens: 12},
      {inputTokens: 20, outputTokens: 3, totalTokens: 23},
    ];
    let received: UsageMetadata | undefined;

    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, u) => {
        received = u;
      },
    };

    const orchestrator = createChatOrchestrator(createMultiRoundProvider(usages), promptBuilder, testRegistry(), {
      hooks,
    });
    await orchestrator.processMessage(session());

    expect(received).toEqual({
      inputTokens: 30,
      outputTokens: 5,
      totalTokens: 35,
    });
  });
});

